import { Button } from "@/registry/erbium/ui/button";
import { toast } from "@/registry/erbium/ui/toast";

export default function ToastQueueExample() {
  return (
    <Button
      variant="outline"
      onClick={() => {
        for (let index = 1; index <= 5; index += 1) {
          toast.add({ timeout: 0, title: `Queue item ${index}` });
        }
      }}
    >
      Show five toasts
    </Button>
  );
}
